#include <stdio.h>
#include <ctype.h>
#include <string.h>
int main() {
    char s[1000], clean[1000]; int k = 0;
    if (fgets(s, sizeof(s), stdin)) {
        for (int i = 0; s[i]; i++) {
            if (isalnum(s[i])) clean[k++] = tolower(s[i]);
        }
        clean[k] = '\0';
        int isPal = 1;
        for (int i = 0; i < k/2; i++) {
            if (clean[i] != clean[k - 1 - i]) { isPal = 0; break; }
        }
        printf("%s\n", isPal ? "true" : "false");
    }
    return 0;
}

